contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: amount to deposit, amount to attempt to collect
    function run(uint depositAmt, uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmt)); require(depositAmt <= 1000000000000000000000000000000);
        // ensure this test contract can fund the deposit
        require(address(this).balance >= depositAmt);

        // Make a deposit of depositAmt
        c.Deposit{value: depositAmt}(); if (__ESBMC_reverted()) return;

        // Read balance before Collect
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // Attempt Collect and record whether it reverted
        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read balance after Collect attempt
        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // GENERAL RULE:
        // Collect never increases the caller's recorded balance: afterBal <= beforeBal.
        // This must hold regardless of success or revert.
        assert(afterBal <= beforeBal);
    }

    receive() external payable {}
}

