pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 depositAmt, uint256 _am) internal {
        depositAmt = bound(depositAmt, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmt);
        try c.Deposit{value: depositAmt}() {} catch { return; }
        uint256 beforeBal;
        try c.balances(address(this)) returns (uint256 __r) { beforeBal = __r; } catch { return; }
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterBal;
        try c.balances(address(this)) returns (uint256 __r) { afterBal = __r; } catch { return; }
        assertTrue(afterBal <= beforeBal);
    }

    function testFuzz_run(uint256 depositAmt, uint256 _am) public {
        _run(depositAmt, _am);
    }

    receive() external payable {}
}
